from pathlib import Path
import json,html,shutil
D=json.loads(Path('src/lessons.json').read_text());out=Path('dist');out.mkdir(exist_ok=True)
for p in Path('public').iterdir():
 if p.is_file():shutil.copy(p,out/p.name)
for f in ['app.js','models.js','diagrams.js','motion.js','style.css']:shutil.copy(Path('src')/f,out/f)
origin='https://howitworks.crawfordgroupholdings.com'
def esc(v):return html.escape(str(v),quote=True)
def page(route,title,desc,body,script=False):
 h=f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{esc(title)} | How It Works</title><meta name="description" content="{esc(desc)}"><link rel="canonical" href="{origin}{route}"><meta property="og:title" content="{esc(title)} | How It Works"><meta property="og:description" content="{esc(desc)}"><meta property="og:type" content="website"><meta property="og:url" content="{origin}{route}"><meta property="og:image" content="{origin}/cgh-logo.jpg"><meta name="theme-color" content="#101719"><link rel="stylesheet" href="/style.css?v=hiw-dark-20261023"><link rel="icon" href="/cgh-logo.jpg">{('<meta name="robots" content="noindex">' if route=='/404' else '')}</head><body><a class="skip" href="#main">Skip to content</a><header class="hiw-header"><a class="brand" href="/" aria-label="How It Works home"><span>How It Works<small>See inside. Understand more.</small></span></a><nav aria-label="Main"><a href="/experiences">Explore</a><a href="/about">Our approach</a><a href="https://whatif.crawfordgroupholdings.com/">What If</a><a href="https://crawfordgroupholdings.com/">Back to CGH</a></nav></header><main id="main">{body}</main><footer><p><strong>How It Works</strong> · See inside. Understand more.</p><p>Free educational resources from Crawford Group Holdings, LLC.</p><nav aria-label="Footer"><a href="/about">About</a><a href="/methodology">Sources &amp; methodology</a><a href="/accessibility">Accessibility</a><a href="https://crawfordgroupholdings.com/">CGH</a><a href="https://whatif.crawfordgroupholdings.com/">What If</a><a href="https://crawfordgroupholdings.com/privacy.html">Privacy</a><a href="mailto:support@crawfordgroupholdings.com">Feedback</a></nav><p class="fine">No account, advertising or personal-data forms. Original teaching illustrations; not engineering predictions or professional advice.</p></footer>{('<script type="module" src="/app.js"></script>' if script else '')}</body></html>'''
 p=out/('index.html' if route=='/' else '404.html' if route=='/404' else route.strip('/')+'/index.html');p.parent.mkdir(parents=True,exist_ok=True);p.write_text(h)
def cards(items):return '<div class="cards">'+''.join(f'<a class="card" href="/{e["slug"]}"><span class="cardnum">{e["id"]:02}</span><span class="eyebrow">{esc(e["category"])}</span><h2>{esc(e["title"])}</h2><p>{esc(e["objective"])}</p><strong>See inside <span aria-hidden="true">↗</span></strong></a>' for e in items)+'</div>'
page('/','A little curiosity. A deeper understanding.','Explore 50 free interactive explanations of everyday mechanisms, technology, the body and nature.', '''<section class="hero"><div><p class="eyebrow">FREE TO EXPLORE · OPEN TO EVERYONE</p><h1>Everyday things.<br><em>Extraordinary<br>connections.</em></h1><p class="lead">See inside. Understand more.</p><p>From a turning bicycle wheel to a beating heart, discover the parts and processes that make your world work.</p><a class="button" href="/experiences">Find your first discovery ↗</a><p class="fine">50 experiences · 5 subjects · No account needed</p></div><a class="heroart" href="/four-stroke-engine" aria-label="Explore inside a four-stroke engine"><span class="eyebrow">LOOK BENEATH THE SURFACE</span><svg viewBox="0 0 480 360" role="img" aria-label="Engine cutaway: piston, connecting rod and crankshaft"><rect x="135" y="20" width="210" height="230" rx="12" fill="#d8eced" stroke="#173b48" stroke-width="5"/><path d="M150 65H330M175 20V55M300 20V55" stroke="#126e8b" stroke-width="12"/><rect x="150" y="125" width="180" height="40" rx="5" fill="#f6c887" stroke="#173b48" stroke-width="4"/><path d="M240 165L280 290" stroke="#173b48" stroke-width="15"/><circle cx="280" cy="290" r="42" fill="#fff" stroke="#173b48" stroke-width="9"/><path d="M280 290L310 270" stroke="#b45b13" stroke-width="10"/><text x="350" y="150" font-size="20" fill="#173b48">Piston</text><text x="25" y="310" font-size="20" fill="#173b48">Crankshaft</text></svg><h2>What turns a spark into motion?</h2><span>Open the engine →</span></a></section><section><p class="eyebrow">THREE WAYS TO MAKE A CONNECTION</p><h2 class="sectiontitle">Watch it. Try it. Understand it.</h2><div class="three"><article><b>01 / Show me</b><h3>Follow the mechanism</h3><p>Play a guided explanation, pause, or move one step at a time.</p></article><article><b>02 / Let me try</b><h3>Take the controls</h3><p>Operate the system and see the reason behind each result.</p></article><article><b>03 / Explain more</b><h3>Go a little deeper</h3><p>Explore terms, misconceptions, model limits and original sources.</p></article></div></section><section><p class="eyebrow">FOLLOW YOUR CURIOSITY</p><h2 class="sectiontitle">A world worth looking into.</h2>'''+cards([D[i] for i in [1,3,15,24,30,49]])+'''</section><section class="mission"><p class="eyebrow">KNOWLEDGE SHOULD OPEN DOORS</p><h2 class="sectiontitle">Everyone deserves a place to learn.</h2><p class="lead">We provide free educational resources so everyone has the opportunity to learn, grow, and access knowledge.</p><p>Understand how it works. Discover what happens when it changes.</p><a href="https://whatif.crawfordgroupholdings.com/">Meet our companion platform, What If ↗</a></section>''')
cats=list(dict.fromkeys(e['category'] for e in D))
page('/experiences','Explore all 50 experiences','Search and filter the complete How It Works catalog.','<section><p class="eyebrow">YOUR NEXT DISCOVERY</p><h1>See what makes it work.</h1><div class="filters"><label for="search">Search experiences<input id="search" type="search" placeholder="Try engines, heart, internet…"></label><label for="category">Subject<select id="category"><option value="">All subjects</option>'+''.join(f'<option>{esc(c)}</option>' for c in cats)+'</select></label></div><p id="count" role="status">50 experiences</p>'+cards(D)+'<p id="empty" hidden>No matches. Try another word or choose all subjects.</p></section>',True)
related={3:('stopping-distance','What if I can’t stop in time?'),4:('power-outage','What if the power goes out?'),5:('power-outage','What if the power goes out?'),11:('power-outage','What if the power goes out?'),33:('sound-and-distance','What if I turn the volume up?'),49:('rainfall-runoff','What if it keeps raining?')}
for e in D:
 i=e['id'];route='/'+e['slug'];sources=''.join(f'<li><a href="{esc(s["url"])}">{esc(s["title"])}</a> · Reviewed {s["reviewed"]}</li>' for s in e['sources'])
 more=f'<h2>Make the connection</h2><p>{esc(e["objective"])}</p>'+''.join(f'<h3>{esc(s["title"])}</h3><p>{esc(s["text"])}</p>' for s in e['stages'])+'<h3>Useful words</h3><dl>'+''.join(f'<dt>{esc(k)}</dt><dd>{esc(v)}</dd>' for k,v in e['terms'].items())+f'</dl><h3>A common misconception</h3><p>{esc(e["misconception"])}</p><h3>Sources</h3><ul>{sources}</ul>'
 body=f'''<section class="lesson" data-lesson="{i}" data-slug="{e['slug']}"><a href="/experiences">← All experiences</a><p class="eyebrow">{i:02} / {esc(e['category'])}</p><h1>{esc(e['title'])}</h1><p class="lead">{esc(e['objective'])}</p><div class="modebar" aria-label="Learning modes"><button data-mode="show" aria-pressed="true">Show me</button><button data-mode="try" aria-pressed="false">Let me try</button><button data-mode="more" aria-pressed="false">Explain more</button></div><div id="visual-panel"><div class="stagehead"><span id="stage-label">Whole system</span><span class="badge">Teaching model</span></div><div class="view-controls"><button id="enlarge" aria-pressed="false">Enlarge diagram</button><span>Use touch or keyboard to pan an enlarged diagram.</span></div><div id="diagram" tabindex="0" aria-label="Diagram viewport"><p>Loading interactive diagram…</p></div><div id="show-controls"><div class="playback"><button id="play" aria-pressed="false">Play</button><button id="previous">Previous step</button><button id="next">Next step</button><button id="restart">Restart</button></div><p id="caption" aria-live="polite">{esc(e['stages'][0]['text'])}</p></div><div id="try-controls" hidden><label for="activity">{esc(e['control']['label'])}</label><select id="activity">{''.join(f'<option value="{n}">{esc(o)}</option>' for n,o in enumerate(e['control']['options']))}</select><button id="reset">Reset activity</button><p id="result" role="status"></p></div><p class="limit"><strong>Model limits:</strong> {esc(e['limits'])}</p><details><summary>Text equivalent of the visual model</summary><p id="visual-text">{esc(e['stages'][0]['text'])}</p><p>{esc(e['misconception'])}</p></details></div><article id="more-panel" hidden>{more}</article><noscript><p>JavaScript enables the guided animation and activity. The complete explanation follows.</p>{more}</noscript><p class="feedback">Found an issue? <a href="mailto:support@crawfordgroupholdings.com?subject=How%20It%20Works%20experience%20{i}">Send feedback about this experience</a>.</p><h2>Keep exploring</h2>'''
 if i in related:
  slug,label=related[i];body+=f'<p><a href="https://whatif.crawfordgroupholdings.com/{slug}">Explore what happens when… {esc(label)}</a></p>'
 body+=cards([D[(i)%50],D[(i+8)%50]])+'</section>'
 page(route,e['title'],e['objective'],body,True)
 p=out/'lessons'/f'{i}.json';p.parent.mkdir(exist_ok=True);p.write_text(json.dumps(e,ensure_ascii=False))
page('/about','A place for curious minds','Our free educational mission and approach.','<section class="prose"><h1>See inside. Understand more.</h1><p class="lead">How It Works explains the systems behind everyday life.</p><p>Created by Crawford Group Holdings, LLC, this platform offers free educational resources so everyone has the opportunity to learn, grow, and access knowledge.</p><p>Use Show me to follow a mechanism, Let me try to explore it, and Explain more to examine its limits and references. No account is required.</p><p>Our companion What If explores the consequences of changing conditions. Together: Understand how it works. Discover what happens when it changes.</p><a href="/experiences">Start exploring →</a></section>')
page('/methodology','Sources and methodology','How we use sources and simplified teaching models.','<section class="prose"><h1>Clear explanations. Visible limits.</h1><p>These are original educational illustrations and deterministic activities, not engineering simulations, medical assessments or financial advice. They omit detail to expose a mechanism. Scale, timing and graphical spacing are schematic unless stated otherwise.</p><p>Each lesson identifies its objective, model assumptions, misconceptions and source links. The review date records the editorial check, not a claim that the source will never change. Institutional and primary technical sources guide the explanations; linking does not imply endorsement.</p><p>Numeric examples use stated assumptions. The AI, QR, wind-power, network and biological demonstrations explicitly identify invented values or qualitative outcomes. They do not reproduce real system internals or guarantee outcomes.</p><p>Electrical, mechanical and biological interactions are virtual. Financial figures are fictional. Send corrections to support@crawfordgroupholdings.com.</p><h2>Source index</h2><ul>'+''.join(f'<li><a href="/{e["slug"]}">{esc(e["title"])}</a>: <a href="{esc(e["sources"][0]["url"])}">{esc(e["sources"][0]["title"])}</a></li>' for e in D)+'</ul></section>')
page('/accessibility','Accessibility','Keyboard controls, reduced motion and text alternatives.','<section class="prose"><h1>Explore at your own pace.</h1><p>All lesson controls use standard buttons and selects. Tab moves between controls; Enter or Space activates buttons; arrow keys operate selects. No dragging is required.</p><p>Guided playback starts only when requested and stops at the final step. Reduced-motion preferences remove diagram transitions; use Previous step and Next step to advance at your own pace. Text captions and visual descriptions communicate essential content.</p><p>The site targets WCAG 2.2 AA. That target is not a certification. Please report barriers to support@crawfordgroupholdings.com with the lesson URL and your device or assistive technology.</p></section>')
page('/404','Page not found','This page could not be found.','<section class="prose"><h1>That path isn’t here.</h1><p>Choose another discovery from the complete catalog.</p><a class="button" href="/experiences">Explore all 50</a></section>')
routes=['/','/experiences','/about','/methodology','/accessibility']+['/'+e['slug'] for e in D]
(out/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{origin}{r}</loc></url>' for r in routes)+'</urlset>')
(out/'robots.txt').write_text(f'User-agent: *\nAllow: /\nSitemap: {origin}/sitemap.xml\n')
if not Path('docs/experience-manifest.json').exists(): Path('docs/experience-manifest.json').write_text(json.dumps([dict(**e,implementation='implemented; qualification pending',tests='pending',deployment='pending') for e in D],indent=2,ensure_ascii=False))
print(f'Built {len(D)} lessons and {len(routes)} indexed pages')
